import{_ as d,c as r,o as a,aj as e}from"./chunks/framework.B5VMNd4r.js";const c=JSON.parse('{"title":"第2章 AI视频创作工具——生成与编辑的开源利器","description":"","frontmatter":{},"headers":[],"relativePath":"handbook/ai-tools/chapter_2.md","filePath":"handbook/ai-tools/chapter_2.md","lastUpdated":1783615807000}'),s={name:"handbook/ai-tools/chapter_2.md"};function n(h,t,o,i,p,l){return a(),r("div",null,[...t[0]||(t[0]=[e(`<h1 id="第2章-ai视频创作工具——生成与编辑的开源利器" tabindex="-1">第2章 AI视频创作工具——生成与编辑的开源利器 <a class="header-anchor" href="#第2章-ai视频创作工具——生成与编辑的开源利器" aria-label="Permalink to “第2章 AI视频创作工具——生成与编辑的开源利器”">​</a></h1><p>AI图片卷完，AI视频更卷。这4个开源模型和3个编辑工具，覆盖从生成到后期全链路。</p><p>我是怕浪猫，这是AI提效工具系列第2章。上章盘点了AI图片工具，这章聊视频。</p><h2 id="_2-1-ai视频生成模型-svd、cogvideox、mochi-1、ltx-video" tabindex="-1">2.1 AI视频生成模型：SVD、CogVideoX、Mochi 1、LTX-Video <a class="header-anchor" href="#_2-1-ai视频生成模型-svd、cogvideox、mochi-1、ltx-video" aria-label="Permalink to “2.1 AI视频生成模型：SVD、CogVideoX、Mochi 1、LTX-Video”">​</a></h2><p>2025年开源AI视频生成领域，4个模型值得关注：</p><p><strong>Stable Video Diffusion (SVD)</strong></p><p>Stability AI出品，基于Stable Diffusion架构扩展到时序维度。</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td>输入</td><td>单张图片（图生视频）</td></tr><tr><td>输出</td><td>14-25帧，576x1024</td></tr><tr><td>显存需求</td><td>12GB起</td></tr><tr><td>帧率</td><td>约6fps（可插帧到24fps）</td></tr><tr><td>许可证</td><td>Community License</td></tr><tr><td>优势</td><td>与SD生态兼容，图生视频效果好</td></tr></tbody></table><p><strong>CogVideoX</strong></p><p>智谱AI出品，支持文生视频和图生视频，中文理解能力强。</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td>输入</td><td>文本/图片</td></tr><tr><td>输出</td><td>6秒，720x480</td></tr><tr><td>显存需求</td><td>8GB（2B模型）/ 16GB（5B模型）</td></tr><tr><td>许可证</td><td>Apache 2.0（2B）/ 每日200次（5B）</td></tr><tr><td>优势</td><td>中文提示词理解好，开源协议友好</td></tr></tbody></table><p><strong>Mochi 1</strong></p><p>Genmo出品，2025年开源视频模型中运动质量最好之一。</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td>输入</td><td>文本</td></tr><tr><td>输出</td><td>5.4秒，848x480</td></tr><tr><td>显存需求</td><td>4 H100 GPU（完整版）/ 1 GPU（量化版）</td></tr><tr><td>许可证</td><td>Apache 2.0</td></tr><tr><td>优势</td><td>运动流畅度高，物理逼真度好</td></tr></tbody></table><p><strong>LTX-Video</strong></p><p>Lightricks出品，主打快速生成。</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td>输入</td><td>文本/图片</td></tr><tr><td>输出</td><td>5秒，768x512</td></tr><tr><td>显存需求</td><td>12GB</td></tr><tr><td>生成速度</td><td>30秒生成5秒视频（A100）</td></tr><tr><td>许可证</td><td>开源</td></tr><tr><td>优势</td><td>速度快，可在单卡上运行</td></tr></tbody></table><p><strong>4模型横评</strong></p><table tabindex="0"><thead><tr><th>维度</th><th>SVD</th><th>CogVideoX</th><th>Mochi 1</th><th>LTX-Video</th></tr></thead><tbody><tr><td>生成方式</td><td>图生视频</td><td>文/图生视频</td><td>文生视频</td><td>文/图生视频</td></tr><tr><td>视频长度</td><td>2-4秒</td><td>6秒</td><td>5.4秒</td><td>5秒</td></tr><tr><td>运动质量</td><td>中</td><td>中</td><td>高</td><td>中高</td></tr><tr><td>画面质量</td><td>高</td><td>中高</td><td>中高</td><td>中</td></tr><tr><td>上手难度</td><td>低</td><td>低</td><td>中</td><td>低</td></tr><tr><td>硬件门槛</td><td>中</td><td>低</td><td>高</td><td>中</td></tr><tr><td>中文支持</td><td>否</td><td>是</td><td>否</td><td>否</td></tr></tbody></table><blockquote><p>选视频模型像选相机：SVD适合从静态图&quot;激活&quot;视频，CogVideoX适合中文场景，Mochi 1追求运动质量，LTX-Video追求速度。</p></blockquote><h2 id="_2-2-comfyui视频工作流-animatediff与svd实战" tabindex="-1">2.2 ComfyUI视频工作流：AnimateDiff与SVD实战 <a class="header-anchor" href="#_2-2-comfyui视频工作流-animatediff与svd实战" aria-label="Permalink to “2.2 ComfyUI视频工作流：AnimateDiff与SVD实战”">​</a></h2><p>ComfyUI不仅能做图片，视频工作流同样强大。</p><p><strong>AnimateDiff</strong></p><p>AnimateDiff是一个让SD模型生成动画的运动模块，原理是在现有SD模型上插入时序层。</p><table tabindex="0"><thead><tr><th>特性</th><th>说明</th></tr></thead><tbody><tr><td>基础模型</td><td>SD1.5/SDXL</td></tr><tr><td>输出</td><td>16帧动画，可循环</td></tr><tr><td>显存</td><td>8GB起</td></tr><tr><td>风格</td><td>继承底模风格</td></tr><tr><td>适用</td><td>动画风格短视频、循环GIF</td></tr></tbody></table><p><strong>SVD工作流</strong></p><p>SVD在ComfyUI中的典型工作流：</p><table tabindex="0"><thead><tr><th>步骤</th><th>节点</th><th>说明</th></tr></thead><tbody><tr><td>1</td><td>Load Image</td><td>加载起始图片</td></tr><tr><td>2</td><td>SVD Image Encoder</td><td>编码图片特征</td></tr><tr><td>3</td><td>SVD Sampler</td><td>采样生成视频帧</td></tr><tr><td>4</td><td>VAE Decode</td><td>解码为像素帧</td></tr><tr><td>5</td><td>Video Combine</td><td>合并为MP4/GIF</td></tr></tbody></table><p><strong>ComfyUI视频工作流效率技巧</strong></p><table tabindex="0"><thead><tr><th>技巧</th><th>效果</th></tr></thead><tbody><tr><td>用LTX-Video替代SVD</td><td>生成速度提升3倍</td></tr><tr><td>先低分辨率生成再超分</td><td>显存节省40%</td></tr><tr><td>用ControlNet控制运动</td><td>运动可预测性大幅提升</td></tr><tr><td>批量生成用API调度</td><td>无人值守批量产出</td></tr><tr><td>AnimateDiff用循环帧</td><td>生成无缝循环动画</td></tr></tbody></table><h2 id="_2-3-autocut-用ai自动剪辑视频的开源神器" tabindex="-1">2.3 AutoCut：用AI自动剪辑视频的开源神器 <a class="header-anchor" href="#_2-3-autocut-用ai自动剪辑视频的开源神器" aria-label="Permalink to “2.3 AutoCut：用AI自动剪辑视频的开源神器”">​</a></h2><p>视频剪辑最耗时的是什么？找素材、剪片段、加字幕。AutoCut用AI自动化这个过程。</p><p><strong>AutoCut工作原理</strong></p><table tabindex="0"><thead><tr><th>输入</th><th>AI处理</th><th>输出</th></tr></thead><tbody><tr><td>视频文件</td><td>Whisper转录</td><td>带时间码的文字稿</td></tr><tr><td>文字稿</td><td>LLM分析关键段落</td><td>自动剪辑决策</td></tr><tr><td>剪辑决策</td><td>FFmpeg执行切割</td><td>输出剪辑后视频</td></tr></tbody></table><p><strong>AutoCut vs 传统剪辑</strong></p><table tabindex="0"><thead><tr><th>维度</th><th>AutoCut</th><th>手动剪辑（Premiere/达芬奇）</th></tr></thead><tbody><tr><td>转录</td><td>自动（Whisper）</td><td>手动或第三方工具</td></tr><tr><td>找片段</td><td>AI标记关键内容</td><td>手动浏览全部素材</td></tr><tr><td>剪辑</td><td>选文字段即剪</td><td>手动切割拼接</td></tr><tr><td>字幕</td><td>自动生成</td><td>手动输入</td></tr><tr><td>效率</td><td>10分钟素材→5分钟出片</td><td>10分钟素材→1小时出片</td></tr><tr><td>精度</td><td>中</td><td>高</td></tr><tr><td>适合</td><td>口播/访谈/会议</td><td>精品内容创作</td></tr></tbody></table><p><strong>安装与使用</strong></p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 安装</span></span>
<span class="line"><span>pip install autodoc-mp4</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 基本用法</span></span>
<span class="line"><span>autocut video.mp4  # 自动转录+剪辑</span></span>
<span class="line"><span>autocut video.mp4 --lang zh  # 指定中文</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><blockquote><p>AutoCut不是要替代专业剪辑师，而是把&quot;从素材到粗剪&quot;这个最无聊的环节自动化。省下的时间用来做创意。</p></blockquote><h2 id="_2-4-whisper-webui-开源语音转文字与自动字幕" tabindex="-1">2.4 Whisper-WebUI：开源语音转文字与自动字幕 <a class="header-anchor" href="#_2-4-whisper-webui-开源语音转文字与自动字幕" aria-label="Permalink to “2.4 Whisper-WebUI：开源语音转文字与自动字幕”">​</a></h2><p>Whisper是OpenAI开源的语音识别模型，Whisper-WebUI给它套了一个网页界面。</p><p><strong>三种转录引擎对比</strong></p><table tabindex="0"><thead><tr><th>引擎</th><th>速度</th><th>显存</th><th>精度</th><th>推荐场景</th></tr></thead><tbody><tr><td>标准Whisper</td><td>标准</td><td>中</td><td>最高</td><td>专业场景</td></tr><tr><td>faster-whisper</td><td>快5倍</td><td>低</td><td>高</td><td>日常使用</td></tr><tr><td>insanely-fast-whisper</td><td>极速</td><td>最低</td><td>中高</td><td>批量处理</td></tr></tbody></table><p><strong>Whisper-WebUI核心功能</strong></p><table tabindex="0"><thead><tr><th>功能</th><th>说明</th></tr></thead><tbody><tr><td>文件转录</td><td>上传音频/视频文件转文字</td></tr><tr><td>YouTube转录</td><td>输入链接直接转录</td></tr><tr><td>麦克风实时转录</td><td>实时语音转文字</td></tr><tr><td>说话人识别</td><td>区分不同说话人</td></tr><tr><td>背景音乐分离</td><td>分离人声和BGM</td></tr><tr><td>多语言支持</td><td>99种语言自动检测</td></tr><tr><td>输出格式</td><td>TXT/SRT/VTT/JSON</td></tr></tbody></table><p><strong>部署方式</strong></p><table tabindex="0"><thead><tr><th>方式</th><th>命令</th><th>适合</th></tr></thead><tbody><tr><td>Docker</td><td>docker compose up</td><td>推荐方式</td></tr><tr><td>Windows</td><td>Install.bat</td><td>非技术用户</td></tr><tr><td>Linux/Mac</td><td>./Install.sh</td><td>命令行用户</td></tr><tr><td>访问地址</td><td><a href="http://localhost:7860" target="_blank" rel="noreferrer">http://localhost:7860</a></td><td>浏览器使用</td></tr></tbody></table><p><strong>Whisper模型选择指南</strong></p><table tabindex="0"><thead><tr><th>模型</th><th>磁盘</th><th>内存</th><th>中文精度</th><th>推荐场景</th></tr></thead><tbody><tr><td>tiny</td><td>75MB</td><td>125MB</td><td>低</td><td>快速预览</td></tr><tr><td>base</td><td>142MB</td><td>210MB</td><td>中低</td><td>测试</td></tr><tr><td>small</td><td>466MB</td><td>600MB</td><td>中</td><td>日常使用</td></tr><tr><td>medium</td><td>1.5GB</td><td>2.1GB</td><td>高</td><td>专业字幕</td></tr><tr><td>large</td><td>2.9GB</td><td>3.3GB</td><td>最高</td><td>精确转录</td></tr></tbody></table><blockquote><p>中文转录建议至少用small模型，medium是性价比最高的选择。large在长音频上精度优势明显。</p></blockquote><h2 id="_2-5-视频后处理工具链-插帧、超分与编码" tabindex="-1">2.5 视频后处理工具链：插帧、超分与编码 <a class="header-anchor" href="#_2-5-视频后处理工具链-插帧、超分与编码" aria-label="Permalink to “2.5 视频后处理工具链：插帧、超分与编码”">​</a></h2><p>AI生成视频通常帧率低、分辨率低，需要后处理提升质量。</p><p><strong>插帧工具</strong></p><table tabindex="0"><thead><tr><th>工具</th><th>原理</th><th>效果</th><th>速度</th></tr></thead><tbody><tr><td>RIFE</td><td>光流+插值</td><td>好</td><td>快</td></tr><tr><td>FILM</td><td>大运动插值</td><td>很好</td><td>中</td></tr><tr><td>AMT</td><td>运动补偿</td><td>好</td><td>快</td></tr><tr><td>ComfyUI-Framer</td><td>节点化集成</td><td>好</td><td>中</td></tr></tbody></table><p><strong>超分辨率工具</strong></p><table tabindex="0"><thead><tr><th>工具</th><th>输入</th><th>输出</th><th>特点</th></tr></thead><tbody><tr><td>Real-ESRGAN</td><td>480p视频</td><td>4K视频</td><td>通用性强</td></tr><tr><td>GFPGAN</td><td>人脸视频</td><td>高清人脸</td><td>人脸增强</td></tr><tr><td>CodeFormer</td><td>低质量视频</td><td>修复+增强</td><td>极端质量恢复</td></tr><tr><td>Topaz Video AI</td><td>任意视频</td><td>8K</td><td>商业工具（对比）</td></tr></tbody></table><p><strong>编码与输出</strong></p><table tabindex="0"><thead><tr><th>编码器</th><th>压缩率</th><th>速度</th><th>兼容性</th></tr></thead><tbody><tr><td>H.264 (x264)</td><td>标准</td><td>快</td><td>所有设备</td></tr><tr><td>H.265 (x265)</td><td>高50%</td><td>中</td><td>现代设备</td></tr><tr><td>AV1</td><td>最高</td><td>慢</td><td>新设备</td></tr><tr><td>ProRes</td><td>无损</td><td>快</td><td>后期制作</td></tr></tbody></table><p><strong>完整后处理工作流</strong></p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>AI生成视频(576p/6fps)</span></span>
<span class="line"><span>    → RIFE插帧(6fps→24fps)</span></span>
<span class="line"><span>    → Real-ESRGAN超分(576p→4K)</span></span>
<span class="line"><span>    → x265编码输出</span></span>
<span class="line"><span>    → 成品(4K/24fps)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><table tabindex="0"><thead><tr><th>步骤</th><th>工具</th><th>耗时(10秒视频)</th></tr></thead><tbody><tr><td>插帧</td><td>RIFE</td><td>约30秒</td></tr><tr><td>超分</td><td>Real-ESRGAN</td><td>约2分钟</td></tr><tr><td>编码</td><td>x265</td><td>约1分钟</td></tr><tr><td>合计</td><td>-</td><td>约4分钟</td></tr></tbody></table><blockquote><p>10秒低分辨率视频，4分钟后变成4K高清。这就是开源工具链的威力。</p></blockquote><hr><p>你最想用AI做哪种视频？口播、动画还是特效？评论区聊聊。</p><p>收藏这章，下次做视频直接照着工具表选。</p><p>关注怕浪猫，下期讲AI写作与内容生成工具——本地大模型+文档对话+翻译，一站式搞定。</p><p>系列进度 2/8 — 下一篇：AI写作与内容生成的开源方案</p>`,67)])])}const u=d(s,[["render",n]]);export{c as __pageData,u as default};
